import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    return (major, minor, patch), pre

def _cmp_ident(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _cmp_pre(p1, p2):
    if p1 is None and p2 is None:
        return 0
    if p1 is None:
        return 1
    if p2 is None:
        return -1
    ids1 = p1.split('.')
    ids2 = p2.split('.')
    for a, b in zip(ids1, ids2):
        c = _cmp_ident(a, b)
        if c != 0:
            return c
    return (len(ids1) > len(ids2)) - (len(ids1) < len(ids2))

def _compare(v1, v2):
    core1, pre1 = _parse(v1)
    core2, pre2 = _parse(v2)
    if core1 != core2:
        return (core1 > core2) - (core1 < core2)
    return _cmp_pre(pre1, pre2)

def semver_sort(versions):
    indexed = list(enumerate(versions))
    def cmp(a, b):
        c = _compare(a[1], b[1])
        if c != 0:
            return c
        return a[0] - b[0]
    indexed.sort(key=functools.cmp_to_key(cmp))
    return [v for _, v in indexed]

